function sumOfMultiples(n: number): number {
  const S = (k: number): number => {
    const m = Math.floor(n / k);
    return (k * m * (m + 1)) / 2;
  };
  return S(3) + S(5) + S(7) - S(15) - S(21) - S(35) + S(105);
}

